"""Commit-bound communication capabilities shipped to every Automation worker."""
from __future__ import annotations


def automation_contract() -> dict:
    return {
        "schema": "adaos.conversational.communication_contract.v1",
        "owner": "Core conversation runtime",
        "channels": [
            {"id": "web", "surface": "browser dialog / YJS", "entrypoint": "adaos.sdk.chat.send",
             "semantics": "canonical transcript projection; browser first-sync is independent of external delivery"},
            {"id": "telegram", "surface": "Core-bound bot/chat or hub pairing ReplyRoute",
             "entrypoint": "adaos.sdk.conversation.publish",
             "semantics": "durable per-target outbox; Root acceptance precedes provider receipt"},
            {"id": "voice", "surface": "Core Voice input and speech output",
             "entrypoint": "adaos.sdk.chat.send(render_targets=('text_tail','speech_text'))",
             "semantics": "existing speech projection and channel capability negotiation; not Telegram delivery"},
            {"id": "stdout", "surface": "Core system notification sink",
             "entrypoint": "Core routing policy", "semantics": "diagnostic sink, not human delivery proof"},
        ],
        "conversation_channels": "general, conversational, builder are conversation namespaces, not transports",
        "package": {
            "declaration": "skill.yaml/scenario.yaml conversational.manifest: conversational/manifest.yaml",
            "sources": ["input.yaml", "entities.yaml", "examples.yaml", "matchers.yaml",
                        "affordances.yaml", "repair.yaml", "output.yaml", "locale.<locale>.yaml", "tests/stories/*.yaml"],
            "scaffold": "adaos.sdk.developer.conversational.scaffold_project",
            "validate": "adaos.sdk.developer.conversational.compile_project",
            "purpose": "package declares semantic intents, workflow commands, outputs and presentation requirements; Core owns routes, authority, transport and recovery",
        },
        "browser_data_route": {
            "scope": "Declare a data_route only for an actual browser data source, not merely because a public conversational tool exists.",
            "tool_read_example": {"surface": "Owned communication routes", "route": "tool", "tool": "get_output_routes",
                "owner": "skill:<owner>", "budget": {"max_items": 20, "max_payload_bytes": 131072},
                "read_policy": {"mode": "explicit", "triggers": ["explicit_refresh"], "max_request_hz": 1,
                    "preserve_last_value": True, "invalidation_tags": ["conversation.output_routes"]}},
        },
        "runtime": {
            "active_chat": "adaos.sdk.conversation.communication_context(webspace_id=...,channel_id='builder'); use its conversation_id/thread_id only when status=ready; unavailable has no fallback",
            "ordinary_reply": "return message/content from the tool; Core materializes the current conversation",
            "human_decision": "adaos.sdk.chat.request / respond; never wait in a local process",
            "background_output": "adaos.sdk.conversation.publish(conversation_id=...,publication_key=stable_semantic_key,text=...,task_ref=...)",
            "context_lifetime": "Resolve communication_context at interactive ingress, then persist that owned conversation_id/thread_id in the task/session. Background completion uses the captured binding; never follow a later active dialog pointer or guess a shared fallback. Core publish still rechecks ownership. Invocation request_id is not a background task identity; use the captured task/output identity.",
            "discover": "adaos.sdk.conversation.output_routes(conversation_id)",
            "select": "adaos.sdk.conversation.select_output_routes(conversation_id,route_ids,response_id=...); Core checks the accepted human interaction, exact route_ids and authenticated actor; future outputs only",
            "defaults": "external mirroring off; use existing Core-admitted routes; inbound origin must not be echoed to the same route",
            "identity": "publication_key identifies one output/content revision; new intentional share uses a new action identity",
            "ownership": "skill may publish only into its owned conversation; credentials and raw bot/chat addresses stay in Core",
            "states": "message committed != projected != Root accepted != provider delivered != human read",
            "recovery": "Core dispatcher leases indexed due intents; transport retry never invokes workflow/LLM/Codex or appends the transcript again",
            "unknown_outcome": "reconcile exact operation_key/receipt; do not blind resend after an ambiguous acknowledgement",
            "receipt_lookup": "Core alone reads Root with the existing Hub mTLS identity. Receipt status v1 returns HTTP 200, found=false, receipt=null, status=not_found for a truthful miss. This is not a missing HTTP route, delivery proof, or permission to resend. Apps must not call Root receipt APIs or acquire peer/admin credentials.",
            "fanout": "one independent intent/envelope per selected target; success on Web cannot close Telegram",
        },
        "response_contracts": {
            "communication_context": {"status": "ready|unavailable", "reason": "string|null",
                "conversation_id": "string|null", "thread_id": "string|null", "owner": "string|null",
                "request_id": "string|null", "verified_user_ref": "string|null", "origin_transport": "string|null",
                "authority": "persisted dialog pointer + owning skill + verified caller; no user-supplied identity fields"},
            "access.invocation": {"request_id": "string|null", "idempotency_key": "string|null",
                "scope": "request/replay identity only; does NOT contain active conversation, actor or confirmation"},
            "output_routes": {"items": [{"route_id": "opaque Core ID", "transport": "telegram|other admitted transport",
                "status": "active|paused|expired|revoked", "expires_at": "ISO8601|null", "selected": "boolean"}],
                "automatic_external_outputs_default": "off", "conversation_id": "string", "policy_revision": "integer",
                "truncated": "boolean; at most 20 principal-scoped routes are returned",
                "empty": "no admitted route; return explicit unavailable, do not create a sender",
                "authority": "Core filters principal_scope and conversation ownership; node pairing is admitted only for verified owner"},
            "select_output_routes": {"result": {"conversation_id": "string", "route_ids": ["opaque route ID"], "policy_revision": "integer"},
                "errors": ["PermissionError: missing caller/owning skill, wrong principal, foreign route, invalid human response", "ValueError: too many routes"],
                "confirmation": "Use chat.request(meta={'purpose':'conversation.output_routes','output_policy_revision':output_routes_result['policy_revision']},...) in the exact owned chat. A real user responds with values.route_ids. Pass the stored accepted response_id to select_output_routes; Core checks exact selection, actor and policy generation and consumes the response once. Never create an accepted response or set a confirmation boolean in application code.",
                "disable": "an empty route_ids list is also confirmed; unsent revoked/deselected targets are suppressed. In a form require output_mode (selected|disabled), not route_ids: the generic interaction validator correctly treats required [] as missing. Include values.route_ids=[] and values.output_mode='disabled' for the explicit disable decision."},
            "route_decision_across_channels": {
                "use": "For Web/Telegram/voice use existing chat.request choice actions. Core select_output_routes also resolves accepted values.choice through interaction.metadata.output_route_choices; it never trusts an application-made confirmation.",
                "input_spec": {"kind": "choice", "required_fields": ["choice"], "choices": [
                    {"value": "enabled", "label": "Enable selected outputs"},
                    {"value": "disabled", "label": "Disable external outputs"}], "sensitive": False},
                "actions": [{"action_id": "enable", "label": "Enable selected outputs", "command": "conversation.output_routes.select", "value": "enabled", "risk": "write", "confirmation_required": True},
                    {"action_id": "disable", "label": "Disable external outputs", "command": "conversation.output_routes.select", "value": "disabled", "risk": "write", "confirmation_required": True}],
                "meta": {"purpose": "conversation.output_routes", "output_policy_revision": "current integer from output_routes",
                    "output_route_choices": {"enabled": ["Core-admitted selected opaque route ID"], "disabled": []}},
                "response_handling": "A normal canonical interaction response has values.choice, not top-level route_ids. Resolve the frozen mapping for the accepted choice, pass that list and actual stored response_id to select_output_routes. Localized labels must describe each exact selection. Core rechecks actor, ownership and policy revision. Do not declare required route_ids on choice input. No automatic enable on discovery.",
            },
            "publish": {"schema": "adaos.conversation.publication_receipt.v1", "publication_id": "string", "message_id": "string",
                "intent_ids": ["string"], "status": "committed", "committed_at": "epoch seconds",
                "errors": ["PermissionError: caller or conversation ownership denied", "ValueError: identity/content conflict or route unavailable"],
                "identity": "reuse publication_key only for the exact same semantic output; route policy changes do not republish history",
                "origin": "Core excludes the ingress Telegram destination using admitted IO metadata; apps never compare bot/chat IDs or issue raw transport calls"},
            "compile_project": {"signature": "compile_project(kind: Literal['skill','scenario'], project_id: str, *, operation_catalog: Mapping[str,Sequence[str]]|None=None, run_stories: bool=True, build_static_report: bool=True) -> dict",
                "project_id": "technical component ID, e.g. builder_skill; not a path or project:<id>",
                "result": {"valid": "boolean", "validation_report": "object with diagnostics/story_reports", "static_report": "object|null", "static_markdown": "string|null", "runtime_bundle": "object|null"},
                "isolated_worker": "Core SDK is absent; run hermetic tests against documented fakes, and report origin compilation as unexecuted. Origin worker owns authoritative compile. Do not invent a local compiler.",
                "origin_example": "compile_project('skill','builder_skill',run_stories=True)"},
        },
        "forbidden_application_alternatives": [
            "transcript/history scans as delivery queues", "app-local receipt JSON/lock directories",
            "second Telegram sender/webhook/polling daemon", "app-side route credentials or authentication",
            "ui.notify plus chat.append for the same semantic output", "content-hash guessing of delivered duplicates",
        ],
        "missing_capability": "return adaos.development_escalations.v1 with an exact Core contract gap; do not implement a parallel transport",
        "acceptance": ["publish retry appends one canonical message", "restart resumes only unfinished outputs",
                       "provider offline cannot block API/YJS", "route revoked/expired or source redacted suppresses unsent output",
                       "Root 202 is not delivered", "cross-conversation route denied"],
    }
